export const ADMIN_ACTIONS=[
 ...Object.entries(STORY).flatMap(([key,lines])=>lines.map((line,i)=>({id:`tv:${key}:${i}`,group:'Сюжет / телевизор',title:line[0],hint:line[1]}))),
 ...SERVER_CHECKPOINTS.map(([id,title])=>({id:'server:'+id,group:'Сисадмин / любое действие',title,hint:'Игрок, предметы, двери и сервер подготовлены к этому этапу.'})),
 ...['Сайт','Заказы','Вход','Файлы'].map((title,i)=>({id:'defense:'+i,group:'Белый хакер / защита',title:'Поток '+(i+1)+' / '+title,hint:'Предыдущие фильтры уже включены.'})),
 ...[['start','Начало / все уязвимости'],['duplicates','Защита переводов от дублей'],['stock','Проверка баланса'],['fixed','Исправлено / запустить проверки'],['tested','Переводы проверены / выпустить']].map(([id,title])=>({id:'developer:'+id,group:'Разработчик / выпуск',title,hint:'Откроется работающий предпросмотр в выбранном состоянии.'})),
 {id:'audit:start',group:'Белый хакер / сеть',title:'Захват узлов сети',hint:'Дополнительная мини-игра.'},
 ...[['custom','Темы базы / Зозон'],['hardware','CPU и GPU / готовая связка'],['loot','Кейс получен / усиления'],['office','Компания / 2D'],['walk','Компания / прогулка 3D'],['cases','Кейсы / начать работу'],['stock','Склад / найм и установка'],['nds','Магазин НДС'],['market','Рынок / свои заявки'],['futures','Фьючерсы / long и short'],['zozon','Зозон / аукцион'],['clans','Кланы / война'],['log','Журнал операций'],['case-running','Кейс / половина работы'],['case-finish','Кейс / перед выплатой'],['own-order','Рынок / свой выставленный лот'],['position-close','Фьючерс открыт / закрыть позицию'],['auction-bid','Аукцион открыт / сделать ставку'],['auction-finish','Аукцион / перед выдачей лота'],['war-running','Клановая война / перед результатом'],['install-ssd','Купленный SSD / установка 3D'],['install-ram','Купленная RAM / установка 3D']].map(([id,title])=>({id:'tycoon:'+id,group:'Тайкон / любой раздел',title,hint:'Отдельная демо-компания с сотрудниками и техникой.'})),
 {id:'classroom:company',group:'Меню',title:'Класс / выбор профессии компании',hint:'Исходная аудитория и три профиля тайкона.'},{id:'modes:select',group:'Меню',title:'Выбор тайкона и квестов',hint:'Экран после финала.'},{id:'quests:select',group:'Меню',title:'Выбор специальности',hint:'Все квесты доступны.'}
];
export function showAdmin({onGo,onClose,onMissionAction,hasMission=false}={}){const d=document.createElement('dialog');d.className='admin-panel';d.innerHTML=`<button class="modal-close" aria-label="Закрыть админку">×</button><header><span>ЦЕНТР ИНВЕСТ БАНК / ПУЛЬТ РЕЖИССЁРА</span><h2>Открыть любой момент.</h2><p>Переход запускает настоящую игру с подготовленным состоянием. Демонстрация не меняет основное сохранение.</p></header><div class="admin-options"><label>Поиск<input id="admin-search" placeholder="Например: SSD, вторая волна, рынок…" autocomplete="off"></label><label>Деньги демо-компании<input id="admin-cash" type="number" min="0" max="1000000000000" value="100000"></label><label>Кубки демо-клана<input id="admin-trophies" type="number" min="0" max="100000" value="5000"></label><label>Профессия демо-компании<select id="admin-profession"><option value="frontend">Разработчик</option><option value="security">Белый хакер</option><option value="sysadmin">Сисадмин</option></select></label><label class="admin-timer-toggle"><input id="admin-timer" type="checkbox"> Таймер миссии включён</label></div>${hasMission?'<div class="admin-quick"><button data-command="win">Завершить текущую миссию</button><button data-command="fail">Показать поражение</button><button data-command="time">Добавить 60 секунд</button><button data-command="freeze">Пауза / запуск таймера</button></div>':''}<div class="admin-destinations"></div><footer>F2 — открыть / закрыть админку · Esc — закрыть · D в сюжетных сценах — следующая реплика</footer>`;document.body.append(d);let chosen=false;const options=()=>({profession:d.querySelector('#admin-profession').value,cash:+d.querySelector('#admin-cash').value,trophies:+d.querySelector('#admin-trophies').value,timer:d.querySelector('#admin-timer').checked});function list(){const term=d.querySelector('#admin-search').value.trim().toLowerCase(),filtered=ADMIN_ACTIONS.filter(a=>(a.title+' '+a.group+' '+a.hint).toLowerCase().includes(term)),box=d.querySelector('.admin-destinations');box.innerHTML='';for(const group of [...new Set(filtered.map(a=>a.group))]){const section=document.createElement('section'),h=document.createElement('h3');h.textContent=group;section.append(h);const grid=document.createElement('div');for(const a of filtered.filter(a=>a.group===group)){const b=document.createElement('button'),title=document.createElement('b'),hint=document.createElement('small');title.textContent=a.title;hint.textContent=a.hint;b.append(title,hint);b.onclick=()=>{const o=options();chosen=true;d.close();onGo(a.id,o);};grid.append(b);}section.append(grid);box.append(section);}if(!filtered.length)box.textContent='Ничего не найдено. Попробуй название действия или профессии.';}
 d.querySelector('.modal-close').onclick=()=>d.close();d.querySelector('#admin-search').oninput=list;d.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{chosen=true;d.close();onMissionAction(b.dataset.command);});d.addEventListener('close',()=>{d.remove();onClose?.(chosen);},{once:true});list();d.showModal();return d;}
